 let randoms = [];
    let r;
    let dis;
    let ranCheck

      
    let ns = 'http://www.w3.org/2000/svg';
    let svg = document.createElementNS(ns, 'svg');

    let widthDoc; 
    let heightDoc;
    let multi;

      // noprotect 
      

      function setup() {

        let hashPairs = [];

        for (let j = 0; j < 32; j++) {
           hashPairs.push(tokenData.hash.slice(2 + (j * 2), 4 + (j * 2)));
        }

        let decPairs = hashPairs.map(x => {
             return parseInt(x, 16);
        });

        // parse the token hash and seed the rng
        let s = parseInt(tokenData.hash.slice(0, 16), 16);

        randomSeed(s);
       

        widthDoc =  (windowHeight/1.2941176470588);
        heightDoc = windowHeight;
        multi = windowHeight/950;
        r = 32;
        dis = 1500;
      
        for(let i =0; i< r; i++){
          let p = createVector(0,0);
          p.x = (random(-dis,dis )*multi) + (widthDoc/2);
          p.y = (random(-dis,dis)*multi) + (heightDoc/2);
          let a = i/r;
          randoms.push(p);
         
        }

        // get rid of the default canvas
        noCanvas();

        // no animation
        noLoop();

        // set the svg attributes
        svg.setAttribute('width', '100vw');
        svg.setAttribute('height', '100vh');
        svg.setAttribute('viewBox', '0 0 ' + widthDoc + ' ' + heightDoc);
        

        ranCheck = decPairs[0];
        
        if(ranCheck>115){
          svg.setAttribute('style', 'background-color:black;');
        }else{
          svg.setAttribute('style', 'background-color:white;');
        }
    
        // append the document bounds
        let bounds = document.createElementNS(ns, 'path');
        bounds.setAttribute('d', `M 0 0 M ${widthDoc} ${heightDoc}`);
        svg.appendChild(bounds);

        create();

        document.body.appendChild(svg);


      }

      function keyPressed() {
                if (keyCode === LEFT_ARROW) {
                 downloadSvg();
                } 
      }

      function downloadSvg()
      {
                let svgElement = document.getElementsByTagName('svg')[0];
                let svg = svgElement.outerHTML;
                let file = new Blob([svg], { type: 'plain/text' });
                let a = document.createElement("a"), url = URL.createObjectURL(file);

                a.href = url;
                a.download = 'exported.svg';    
                document.body.appendChild(a);
                a.click();

                setTimeout(function() 
                {
                    document.body.removeChild(a);
                    window.URL.revokeObjectURL(url);  
                }, 0); 

      }

      function exponentialIn(t) {
          return t == 0.0 ? t : pow(2.0, 10.0 * (t - 1.0));
      }

      function createDot(x,y){

                let dot = document.createElementNS(ns, "polyline");
                dot.setAttributeNS(null, "points", `${x} ${y} ${x} ${y}`);
                dot.setAttributeNS(null, "fill", "none");

                if(ranCheck>115){
                  dot.setAttributeNS(null, "stroke", "white");
                }else{
                  dot.setAttributeNS(null, "stroke", "black");
                }
                
                if(windowHeight < 1200){
                  dot.setAttributeNS(null, "stroke-width", multi);
                }else{
                  dot.setAttributeNS(null, "stroke-width", 1.75);
                }
                
               
                dot.setAttributeNS(null, "stroke-linecap", "round")
                svg.appendChild(dot);

      }



      function create() {
       
                let steps = 768;
                let w= random(0,50)*multi;
                let m = random(0,3);
                let cen = createVector((widthDoc/2) , (heightDoc/2));
                cen.x += sin(2*PI*random(-PI,PI))*random(0,(widthDoc/2))*multi;
                  cen.y += cos(2*PI*random(-PI,PI))*random(0,(widthDoc/2))*multi;

                  for(let i = 0; i<steps;i++){
                    
                    for(let j =0; j < r; j++){
                       
                      let prog = i/steps;

                      let tar = createVector(0, 0);
                      
                      if(j == 0){
                        tar = randoms[r-1];
                      }else{
                        tar = randoms[j-1];
                      }
                      
                      let c = createVector((sin(2*PI*prog*m)*w) + cen.x,(cos(2*PI*prog*m)*w) + cen.y);
                      tar.lerp(c,exponentialIn(prog));
                      
                            let posN = createVector(0, 0); 
                      posN = randoms[j];
                      posN.lerp(tar,exponentialIn(prog));
                    
                      let points = 15;
                      
                      for(let o=0 ; o < points; o++){
                       
                          let a = o/points;
                          tar.lerp(posN,a);
                          if(tar.x > 0 && tar.y > 0 && tar.x <= widthDoc && tar.y <= heightDoc ){
                            createDot(tar.x, tar.y);
                          
                          }
                      }
                     
                }
                      
              }
        
           
      }
